CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('owner','admin','member'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE upload_status AS ENUM ('queued','scanning','completed','failed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE data_category AS ENUM ('identity','contact','financial','health','children','location','credentials','other'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE sensitivity_level AS ENUM ('low','medium','high','critical'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE finding_status AS ENUM ('open','in_progress','resolved','accepted_risk'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE document_type AS ENUM ('consent_notice','retention_schedule','breach_playbook'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE erasure_status AS ENUM ('received','in_progress','completed','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,sector text,size_band text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'owner',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS uploads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users,file_name text NOT NULL,file_type text NOT NULL,size_bytes integer NOT NULL,file_sha256 text NOT NULL,row_count integer,status upload_status NOT NULL DEFAULT 'queued',error text,uploaded_at timestamptz NOT NULL DEFAULT now(),scanned_at timestamptz);
CREATE TABLE IF NOT EXISTS fields(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,upload_id uuid NOT NULL REFERENCES uploads ON DELETE CASCADE,field_name text NOT NULL,detectors text[] NOT NULL DEFAULT '{}',match_rate numeric(5,2),category data_category NOT NULL DEFAULT 'other',sensitivity sensitivity_level NOT NULL DEFAULT 'low',masked_samples jsonb NOT NULL DEFAULT '[]',ai_label text,ai_confidence numeric(3,2),ai_reasoning text,user_override boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,upload_id uuid REFERENCES uploads ON DELETE CASCADE,field_id uuid REFERENCES fields ON DELETE CASCADE,rule_code text NOT NULL,severity sensitivity_level NOT NULL,title text NOT NULL,explanation text NOT NULL,recommendation text NOT NULL,status finding_status NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS risk_scores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,score integer NOT NULL CHECK(score BETWEEN 0 AND 100),breakdown jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,type document_type NOT NULL,title text NOT NULL,content text NOT NULL,version integer NOT NULL DEFAULT 1,generated_from jsonb NOT NULL DEFAULT '{}',created_by uuid REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS erasure_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,requester_ref text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz NOT NULL,status erasure_status NOT NULL DEFAULT 'received',notes text,completed_at timestamptz);
CREATE TABLE IF NOT EXISTS ai_calls(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,upload_id uuid REFERENCES uploads ON DELETE CASCADE,provider text NOT NULL,model text NOT NULL,purpose text NOT NULL,masked_payload jsonb NOT NULL,payload_sha256 text NOT NULL,tokens_in integer,tokens_out integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workspace_connectors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,provider text NOT NULL CHECK(provider='google'),account_email text NOT NULL,access_token_enc text NOT NULL,refresh_token_enc text,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,provider));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,org_id uuid NOT NULL REFERENCES organizations ON DELETE CASCADE,user_id uuid REFERENCES users,action text NOT NULL,entity_type text,entity_id uuid,metadata jsonb NOT NULL DEFAULT '{}',ip_address inet,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_uploads_org ON uploads(org_id,uploaded_at DESC); CREATE INDEX IF NOT EXISTS idx_fields_org ON fields(org_id,sensitivity); CREATE INDEX IF NOT EXISTS idx_findings_org ON findings(org_id,status,severity); CREATE INDEX IF NOT EXISTS idx_risk_org ON risk_scores(org_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_documents_org ON documents(org_id,type,version DESC); CREATE INDEX IF NOT EXISTS idx_erasure_org ON erasure_requests(org_id,due_at); CREATE INDEX IF NOT EXISTS idx_ai_calls_org ON ai_calls(org_id,created_at DESC); CREATE INDEX IF NOT EXISTS idx_audit_org ON audit_logs(org_id,created_at DESC);
